// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzzed params: an address array pointer is not a valid fuzz param in forge directly,
    // so we fuzz a single uint256 n (length) and up to 6 addresses packed as params
    // to build an array. This keeps domain wide but lets fuzzer find lengths > 0.
    function testFuzz_property(uint256 n, address a0, address a1, address a2, address a3, address a4, address a5) public {
        // keep n in a reasonable bound to avoid out-of-gas in test harness
        uint256 len = bound(n, 0, 6);

        // Build dynamic array of addresses of length `len` from provided fuzzed addresses
        address[] memory tos = new address[](len);
        if (len > 0) tos[0] = a0;
        if (len > 1) tos[1] = a1;
        if (len > 2) tos[2] = a2;
        if (len > 3) tos[3] = a3;
        if (len > 4) tos[4] = a4;
        if (len > 5) tos[5] = a5;

        // We route the external calls to a simple recording callee that implements
        // transferFrom(address,address,uint256) so the low-level call from C is well-formed.
        // The recording callee will always succeed; the key distinction here is that the
        // reference contract never performs an out-of-bounds access when len>0, so the call
        // completes and c.transfer returns true. The mutant with i<=_tos.length will revert
        // for some inputs (len>0) due to out-of-bounds and thus transfer will not return true.
        Recorder rec = new Recorder();
        address from = address(0xABCD);

        // Call transfer and observe whether it completes (returns) or reverts via try/catch.
        bool ok;
        try c.transfer(from, address(rec), tos, 1) returns (bool r) {
            ok = r; // should be true for reference contract for all inputs (including len==0? reference requires >0)
        } catch {
            ok = false;
        }

        // General rule (single assertion): For any admissible inputs, when _tos.length > 0 the reference
        // contract completes and returns true. The mutant can revert for some inputs with _tos.length>0.
        // We assert: if len > 0 then c.transfer returned true (ok == true).
        // This will hold for the reference implementation for all fuzz inputs, and fail for the mutant
        // when it triggers the out-of-bounds access.
        if (len > 0) {
            assertTrue(ok);
        } else {
            // When len == 0 the function has a require(_tos.length > 0) so it reverts; both versions revert.
            // We do not assert in that branch to avoid making the property falsified by the require.
            assertTrue(true);
        }
    }
}

// Minimal recording helper that exposes the exact function selector C calls via abi.encodeWithSelector
contract Recorder {
    // record last call count and arguments (not used by test, but realistic recorder)
    uint256 public calls;
    event Called(address from, address to, uint256 v);

    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        emit Called(from, to, v);
        return true;
    }
}
